GOLD_V5_106_110_SPEC_PATCHES={
"0106":S("0106",authorial_intent="Turn Art Studio Colors into a material-and-surface laboratory: soft, rough, glossy, absorbent, rigid, flexible, opaque and transparent behaviors drive the song more than naming colors.",lyric_identity="A child predicts what a material will feel or look like before making a mark, then compares the result.",image_motifs=("felt softness","glitter reflection","watercolor wash","clay pressure mark","unfinished wood grain"),semantic_arc=("touch/texture","mark/absorbency","shape/form","finish/reflection"),forbidden_generic_language=("art studio colors","paint with me","everything colorful","sparkle means better"),rhyme_engine="material-texture-response-rhyme",chorus_rhyme_engine="soft-rough-wet-dry-hook",point_of_view="a child comparing art-material behavior",chorus_function="reset material contrasts",groove_meter="88 BPM tactile 6/8",round1_grammar="material -> physical property -> art consequence",round2_grammar="property recall -> target -> safe gesture",intro_lines=("Felt stays soft, watercolor spreads with water, clay changes under pressure.","Art materials answer differently when we touch, fold, roll, or paint them."),hook_lines=("Soft, rough, wet, dry—A-B-C!","Material changes the mark we see."),outro_lines=("Watercolor dries, clay keeps its pressed shape, unfinished wood stays unvarnished.","A to Z leaves the studio as a shelf of different material behaviors."),style_blueprint="Tactile art-pop at 88 BPM with nylon guitar, marimba, brushed drum and soft bass. Texture sections change articulation rather than adding noisy SFX; watercolor gets legato space, felt muted attacks, reflective materials brief high notes.",signature_color="material-texture",cue_prefix="Texture check"),
"0107":S("0107",authorial_intent="Make Craft Box Bounce a planning song: choose a material for the intended result, test a small area, join or color it, then clean and store; decorative choices come after structure.",lyric_identity="A child opens a craft box with a tiny plan instead of grabbing every material.",image_motifs=("apron before paint","small glue test","leaf-print trial","roller coverage","varnish adult finish"),semantic_arc=("plan","test","make","clean/finish"),forbidden_generic_language=("craft box bounce","grab a color","use everything","craft chaos"),rhyme_engine="craft-plan-test-rhyme",chorus_rhyme_engine="plan-test-make-hook",point_of_view="a child following a simple craft plan",chorus_function="repeat plan-test-make-clean",groove_meter="92 BPM stop-check-go",round1_grammar="tool/material -> intended effect -> boundary",round2_grammar="choice recall -> exact target -> pretend-safe action",intro_lines=("Before the box opens: what are we making, what surface are we using, and which tool fits?","A small plan keeps a craft from becoming a pile of supplies."),hook_lines=("Plan, test, make—A-B-C!","Choose one material because it fits the job."),outro_lines=("Marker capped, brush rinsed, varnish left to the adult, scraps collected.","A to Z closes the craft box with the plan completed."),style_blueprint="Playful stop-check art groove at 92 BPM with ukulele, muted claps, marimba and bass. Use short rests before selection words, fuller chorus after the test stage, and a stripped cleanup ending.",signature_color="plan-test",cue_prefix="Craft choice"),
"0108":S("0108",authorial_intent="Make Draw Paint Sing about mark language: line, edge, wash, dab, print, roll, resist, coil and three-dimensional modeling are distinct ways to build an image.",lyric_identity="A child notices how the hand motion changes the mark, without pretending pointed or sharp tools are child actions.",image_motifs=("brush stroke","leaf print","roller band","wax resist","quilled coil"),semantic_arc=("line","surface mark","print/texture","3D and assembled marks"),forbidden_generic_language=("draw paint sing","make a picture","every tool draws","paint everything"),rhyme_engine="mark-motion-internal-rhyme",chorus_rhyme_engine="line-dab-roll-hook",point_of_view="a child reading mark-making techniques",chorus_function="cycle mark verbs",groove_meter="85 BPM variable-stroke 4/4",round1_grammar="tool/material -> mark type -> visual result",round2_grammar="mark-type recall -> target -> empty-hand trace",intro_lines=("A brush pulls a stroke, a sponge can dab, a leaf can print, a roller can lay a band.","Different motions leave different visual evidence."),hook_lines=("Line, dab, roll—A-B-C!","The motion writes its own kind of mark."),outro_lines=("One wax line resists the wash; one quilled strip keeps its coil.","A to Z ends with many mark languages on one studio wall."),style_blueprint="Art-song at 85 BPM with piano, nylon guitar, marimba and brush percussion. Melody changes articulation to mimic long stroke, dot, roll and coil; never use literal scissor or needle sounds.",signature_color="mark-language",cue_prefix="Mark recall"),
"0109":S("0109",authorial_intent="Turn Creative Tool Trail into a classification trail: tool, material, surface, image, finish, and wearable protection are separate categories, preventing phrases like 'paint is a tool' or 'drawing is an object tool'.",lyric_identity="A child labels what each studio thing is before saying what it does.",image_motifs=("apron protection","canvas surface","ink material","loom tool","drawing result"),semantic_arc=("protect/surface","tools","materials","results/finishes"),forbidden_generic_language=("creative tools","everything is a tool","tool trail","make and name carefully"),rhyme_engine="tool-material-result-rhyme",chorus_rhyme_engine="tool-material-result-hook",point_of_view="a child classifying studio roles",chorus_function="reset category labels",groove_meter="90 BPM walking 4/4",round1_grammar="category -> function -> distinction",round2_grammar="category-neutral recall -> target -> safe gesture",intro_lines=("Canvas is a surface, paint is a material, brush is a tool, drawing is a result.","Creative work gets clearer when those roles do not blur."),hook_lines=("Tool, material, result—A-B-C!","Name the role before the action."),outro_lines=("Varnish stays a finish, velvet paper stays a surface, drawing stays the image.","A to Z leaves the trail sorted by role."),style_blueprint="Walking art-pop at 90 BPM with guitar, soft bass, woodblock and marimba; give each category a distinct two-note motif. Keep the mix dry around category words and thin the ending into four separated motifs.",signature_color="category-role",cue_prefix="Role check"),
"0110":S("0110",authorial_intent="Make Make Create A-Z a build sequence from idea to support, shaping, joining, surface treatment, decoration and finish, with rework welcomed instead of pretending every first attempt is final.",lyric_identity="A child maker changes a plan when a material behaves differently than expected; creating includes testing and revising.",image_motifs=("pencil plan","canvas support","glue join","roller surface","finished zipper craft"),semantic_arc=("idea/support","shape/join","color/surface","finish/revise"),forbidden_generic_language=("make create","little makers","perfect first try","magic craft"),rhyme_engine="maker-revision-chain-rhyme",chorus_rhyme_engine="plan-build-revise-hook",point_of_view="a child maker revising a project",chorus_function="repeat plan-build-revise",groove_meter="89 BPM constructive 6/8",round1_grammar="object fact tied to stage without false causality",round2_grammar="stage-neutral retrieval -> target -> safe gesture",intro_lines=("A pencil idea can change after the first piece of felt bends or the first strip of tape pulls.","Making is a loop: plan, build, look, revise."),hook_lines=("Plan, build, revise—A-B-C!","A good maker can change the next step."),outro_lines=("The last piece is checked, not called perfect just because it is finished.","A to Z closes one project and saves what we learned for the next."),style_blueprint="Warm maker-folk at 89 BPM with acoustic guitar, pizzicato, marimba and soft hand percussion. Arrangement starts sketch-thin, gains layers through joining, then removes layers during revision before a clean final cadence.",signature_color="maker-revision",cue_prefix="Maker recall"),
}
